Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -26,4 +26,20 @@
 </div></section>
 <footer class="footer"><div class="legend"><span><b class="key">WASD</b> Move</span><span><b class="key">SPACE</b> Strike</span><span><b class="key">SHIFT</b> Roll</span></div><div class="foot-note">Hold the road. Keep the light.</div></footer>
 </main>
 <script>
+(()=>{
+const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d');
+const ui={healthFill:document.getElementById('healthFill'),healthText:document.getElementById('healthText'),waveText:document.getElementById('waveText'),waveLabel:document.getElementById('waveLabel'),killText:document.getElementById('killText'),toast:document.getElementById('toast'),overlay:document.getElementById('overlay'),title:document.getElementById('overlayTitle'),copy:document.getElementById('overlayCopy'),kicker:document.getElementById('overlayKicker'),start:document.getElementById('startBtn'),hint:document.getElementById('overlayHint')};
+const W=960,H=540,keys={},rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));let scale=1,last=0,toastTimer=0,gameState='title',wave=1,kills=0,spawnTimer=0,remaining=0,shake=0,sound=false,audio;
+const player={x:480,y:365,hp:100,max:100,face:1,attack:0,attackCd:0,roll:0,rollCd:0,invuln:0,walk:0};let enemies=[],particles=[],embers=[],decor=[];
+function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);scale=canvas.width/W;ctx.setTransform(scale,0,0,scale,0,0)}new ResizeObserver(resize).observe(canvas);resize();
+function initScene(){decor=[];embers=[];for(let i=0;i<34;i++)decor.push({x:rand(20,W-20),y:rand(255,468),r:rand(1,3),a:rand(.08,.32)});for(let i=0;i<35;i++)embers.push({x:rand(0,W),y:rand(120,H),v:rand(5,20),s:rand(1,2.5),a:rand(.25,.7)})}initScene();
+function startGame(){player.x=480;player.y=365;player.hp=100;player.face=1;player.attack=0;player.attackCd=0;player.roll=0;player.rollCd=0;kills=0;wave=1;enemies=[];particles=[];remaining=3;spawnTimer=.4;gameState='playing';ui.overlay.classList.add('hidden');notify('THE FORSAKEN ROAD');updateHud()}
+function showEnd(win){gameState=win?'won':'dead';ui.kicker.textContent=win?'Dawn breaks':'The light is lost';ui.title.innerHTML=win?'Hollowmere<br>remembers':'The night<br>claims all';ui.copy.textContent=win?'Three waves have fallen. The road is quiet, and a pale dawn finds the last knight still standing.':'The lantern gutters out, and the forsaken road falls silent. Rise again, knight.';ui.start.textContent=win?'Ride again':'Rise again';ui.hint.textContent='Tap or press ENTER to begin again';ui.overlay.classList.remove('hidden')}
+function updateHud(){ui.healthFill.style.width=(player.hp/player.max*100)+'%';ui.healthText.textContent=Math.ceil(player.hp)+' / 100';ui.waveText.textContent=`WAVE ${wave} / 3`;ui.waveLabel.textContent=wave===1?'NIGHTFALL':wave===2?'THE HUNT':'LAST LIGHT';ui.killText.textContent=kills}
+function notify(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=1.8}
+function spawnEnemy(){let type=(wave===1?Math.random()<.68:'x')? 'goblin':'skeleton';if(wave===3&&Math.random()<.48)type='skeleton';const side=Math.random()<.5?-1:1;enemies.push({type,x:side<0?rand(70,170):rand(790,890),y:rand(305,420),hp:type==='goblin'?2:3,max:type==='goblin'?2:3,speed:type==='goblin'?rand(38,51):rand(25,34),face:side<0?1:-1,attack:rand(.3,1),flash:0,walk:rand(0,6),dead:false});remaining--}
+function puff(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-75,75),vy:rand(-100,35),life:rand(.25,.65),max:.65,size:rand(2,5),color})}
+function beginAttack(){if(gameState!=='playing'||player.attackCd>0||player.roll>0)return;player.attack=.25;player.attackCd=.48;playTone(170,.07,'sawtooth',.025);for(const e of enemies){if(e.dead)continue;const dx=e.x-player.x,dy=e.y-player.y;if(Math.abs(dx)<88&&Math.abs(dy)<58&&(Math.sign(dx)===player.face||Math.abs(dx)<23)){e.hp--;e.flash=.16;puff(e.x,e.y-16,'#f2c579',6);shake=4;playTone(95,.08,'triangle',.045);if(e.hp<=0){e.dead=true;kills++;puff(e.x,e.y,'#b8d5d0',14);if(Math.random()<.16)player.hp=Math.min(100,player.hp+12);updateHud()}}}}
+function dodge(){if(gameState!=='playing'||player.rollCd>0)return;player.roll=.24;player.rollCd=.75;player.invuln=.31;playTone(260,.09,'triangle',.02)}
+function playTone(freq,duration,type='sine',volume=.025){if(!sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}

input.newString:
catch{}}
function update(dt){if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=130*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);for(const e of embers){e.y-=e.v*dt;if(e.y<130){e.y=H-35;e.x=rand(0,W)}}if(gameState!=='playing')return;
player.attackCd=Math.max(0,player.attackCd-dt);player.attack=Math.max(0,player.attack-dt);player.rollCd=Math.max(0,player.rollCd-dt);player.roll=Math.max(0,player.roll-dt);player.invuln=Math.max(0,player.invuln-dt);
let mx=(keys.ArrowRight||keys.KeyD?1:0)-(keys.ArrowLeft||keys.KeyA?1:0),my=(keys.ArrowDown||keys.KeyS?1:0)-(keys.ArrowUp||keys.KeyW?1:0);if(mx&&my){mx*=.707;my*=.707}if(mx)player.face=Math.sign(mx);let speed=player.roll>0?420:190;player.x=clamp(player.x+mx*speed*dt,60,900);player.y=clamp(player.y+my*speed*dt,278,463);player.walk+=dt*(mx||my?10:2);if(player.roll>0&&!mx&&!my)player.x=clamp(player.x+player.face*speed*dt,60,900);
if(remaining>0){spawnTimer-=dt;if(spawnTimer<=0){spawnEnemy();spawnTimer=wave===1?1.7:wave===2?1.35:1.05}}
for(const e of enemies){if(e.dead)continue;e.flash=Math.max(0,e.flash-dt);e.walk+=dt*6;const dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy);e.face=dx<0?-1:1;if(d>34){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*.65*dt}else{e.attack-=dt;if(e.attack<=0){e.attack=e.type==='goblin'?1.05:1.3;if(player.invuln<=0){player.hp=Math.max(0,player.hp-(e.type==='goblin'?7:10));player.invuln=.48;shake=7;puff(player.x,player.y-15,'#cf5960',5);playTone(66,.14,'sawtooth',.045);updateHud();if(player.hp<=0)showEnd(false)}}}}
enemies=enemies.filter(e=>!e.dead);if(remaining===0&&enemies.length===0){if(wave<3){wave++;remaining=wave===2?5:6;spawnTimer=1.6;player.hp=Math.min(100,player.hp+15);updateHud();notify(wave===2?'THE HUNT BEGINS':'THE LAST LIGHT')}else showEnd(true)}if(shake>0)shake=Math.max(0,shake-dt*20)}
function draw(){ctx.save();if(shake){ctx.translate(rand(-shake,shake),rand(-shake,shake))}drawWorld();drawDecor();drawEnemies();drawPlayer();drawParticles();drawEmbers();ctx.restore();requestAnimationFrame(frame)}
function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function drawWorld(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#12182c');sky.addColorStop(.52,'#252239');sky.addColorStop(1,'#46303a');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// distant moon and wisps
ctx.save();ctx.shadowColor='#d9d3ba';ctx.shadowBlur=28;ctx.fillStyle='#ded9c5';ctx.beginPath();ctx.arc(756,112,39,0,Math.PI*2);ctx.fill();ctx.restore();ctx.fillStyle='#b8b2a7';ctx.beginPath();ctx.arc(770,100,36,0,Math.PI*2);ctx.fill();
for(let i=0;i<60;i++){let x=(i*173+31)%W,y=(i*97+21)%220;ctx.globalAlpha=.2+(i%4)*.11;ctx.fillStyle=i%8===0?'#f0d7a2':'#e5e3dd';ctx.fillRect(x,y,(i%7===0?2:1),1.5)}ctx.globalAlpha=1;
// cloud bands
for(let i=0;i<5;i++){let x=(i*240-100);ctx.fillStyle='#74708318';ctx.beginPath();ctx.ellipse(x+100,176+(i%2)*30,150,15,0,0,Math.PI*2);ctx.fill()}
// mountain ridge
ctx.fillStyle='#272538';ctx.beginPath();ctx.moveTo(0,268);ctx.lineTo(115,209);ctx.lineTo(190,258);ctx.lineTo(325,191);ctx.lineTo(451,266);ctx.lineTo(588,218);ctx.lineTo(721,269);ctx.lineTo(843,206);ctx.lineTo(960,262);ctx.lineTo(960,364);ctx.lineTo(0,364);ctx.fill();
// crooked castle silhouette
ctx.fillStyle='#191a29';ctx.beginPath();ctx.moveTo(365,287);ctx.lineTo(365,202);ctx.lineTo(383,202);ctx.lineTo(383,170);ctx.lineTo(398,195);ctx.lineTo(398,215);ctx.lineTo(416,215);ctx.lineTo(416,174);ctx.lineTo(432,150);ctx.lineTo(448,174);ctx.lineTo(448,210);ctx.lineTo(465,210);ctx.lineTo(465,184);ctx.lineTo(481,184);ctx.lineTo(481,224);ctx.lineTo(497,224);ctx.lineTo(497,196);ctx.lineTo(510,178);ctx.lineTo(526,199);ctx.lineTo(526,286);ctx.closePath();ctx.fill();ctx.fillRect(378,224,132,72);ctx.fillStyle='#d5a96d';for(const [x,y] of [[392,242],[421,222],[450,245],[484,232],[508,251]]){ctx.globalAlpha=.45;ctx.fillRect(x,y,5,12)}ctx.globalAlpha=1;
// treeline silhouettes
for(let i=0;i<15;i++){let x=i*75-25,h=randTree(i);ctx.fillStyle=i%2?'#171a26':'#1c1c2a';ctx.beginPath();ctx.moveTo(x-37,367);ctx.lineTo(x,220-h);ctx.lineTo(x+37,367);ctx.closePath();ctx.fill();ctx.fillRect(x-4,328,8,50)}
// rolling ground
let grd=ctx.createLinearGradient(0,280,0,H);grd.addColorStop(0,'#34303a');grd.addColorStop(.28,'#242630');grd.addColorStop(1,'#171b24');ctx.fillStyle=grd;ctx.beginPath();ctx.moveTo(0,330);ctx.quadraticCurveTo(240,302,474,344);ctx.quadraticCurveTo(700,385,960,323);ctx.lineTo(960,540);ctx.lineTo(0,540);ctx.fill();
// path
ctx.fillStyle='#51424a';ctx.beginPath();ctx.moveTo(366,335);ctx.quadraticCurveTo(445,328,508,342);ctx.lineTo(768,540);ctx.lineTo(119,540);ctx.closePath();ctx.fill();ctx.fillStyle='#66504d';ctx.globalAlpha=.34;ctx.beginPath();ctx.moveTo(423,340);ctx.lineTo(472,340);ctx.lineTo(600,540);ctx.lineTo(484,540);ctx.closePath();ctx.fill();ctx.globalAlpha=1;
// path stones
for(let i=0;i<22;i++){let y=370+(i*29)%178,x=440+Math.sin(i*9)*((y-335)*.8);ctx.fillStyle=i%2?'#807067':'#75655e';ctx.globalAlpha=.35;ctx.beginPath();ctx.ellipse(x,y,rand(6,15),3,rand(-.2,.2),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// graveyard crosses / lantern
for(const x of [165,233,803,861]){ctx.fillStyle='#55515a';ctx.fillRect(x,327,5,36);ctx.fillRect(x-9,337,23,5);ctx.fillStyle='#8c7657';ctx.fillRect(x-1,347,2,12)}
// fire lanterns
for(const x of [80,875]){ctx.fillStyle='#40303a';ctx.fillRect(x-2,317,4,50);ctx.fillRect(x-9,363,18,4);ctx.save();ctx.shadowColor='#ffb455';ctx.shadowBlur=20;ctx.fillStyle='#ffc777';ctx.beginPath();ctx.arc(x,315,5,0,Math.PI*2);ctx.fill();ctx.restore();ctx.fillStyle='#d37b48';ctx.fillRect(x-1,322,2,8)}
// ground vignette
let vig=ctx.createRadialGradient(480,330,180,480,330,600);vig.addColorStop(0,'#090d1600');vig.addColorStop(1,'#080a13bd');ctx.fillStyle=vig;ctx.fillRect(0,0,W,H)}
function randTree(i){return 20+((i*47)%74)}

