+function drawEmbers(){for(const e of embers){ctx.globalAlpha=e.a*(.6+.4*Math.sin(e.y*.04));ctx.fillStyle='#ffbf76';ctx.beginPath();ctx.arc(e.x,e.y,e.s,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
+function frame(now){const dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);draw()}
+function pressAction(a){if(a==='attack')beginAttack();else dodge()}
+document.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','ShiftLeft','ShiftRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='Space')beginAttack();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dodge();if(e.code==='Enter'&&(gameState==='title'||gameState==='dead'||gameState==='won'))startGame()});document.addEventListener('keyup',e=>{keys[e.code]=false});window.addEventListener('blur',()=>{for(const k in keys)keys[k]=false});
+document.querySelectorAll('.touch-btn[data-key]').forEach(btn=>{const code=btn.dataset.key;const down=e=>{e.preventDefault();keys[code]=true;btn.classList.add('down');btn.setPointerCapture?.(e.pointerId)};const up=e=>{e.preventDefault();keys[code]=false;btn.classList.remove('down')};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up)});document.querySelectorAll('.touch-btn[data-action]').forEach(btn=>{btn.addEventListener('pointerdown',e=>{e.preventDefault();pressAction(btn.dataset.action);btn.classList.add('down')});for(const ev of ['pointerup','pointercancel','lostpointercapture'])btn.addEventListener(ev,()=>btn.classList.remove('down'))});
+ui.start.addEventListener('click',startGame);canvas.addEventListener('pointerdown',e=>{if(gameState==='playing'&&e.pointerType==='mouse')beginAttack()});document.getElementById('soundBtn').addEventListener('click',e=>{sound=!sound;e.currentTarget.innerHTML=sound?'♫ &nbsp; SOUND: ON':'♫ &nbsp; SOUND: OFF';if(sound)playTone(440,.12,'sine',.02)});
+updateHud();requestAnimationFrame(frame);
+})();
+</script>
+</body>
+</html>
+

