 function startGame(){player.x=480;player.y=365;player.hp=100;player.face=1;player.attack=0;player.attackCd=0;player.roll=0;player.rollCd=0;kills=0;wave=1;enemies=[];particles=[];remaining=3;spawnTimer=.4;gameState='playing';ui.overlay.classList.add('hidden');notify('THE FORSAKEN ROAD');updateHud()}
 function showEnd(win){gameState=win?'won':'dead';ui.kicker.textContent=win?'Dawn breaks':'The light is lost';ui.title.innerHTML=win?'Hollowmere<br>remembers':'The night<br>claims all';ui.copy.textContent=win?'Three waves have fallen. The road is quiet, and a pale dawn finds the last knight still standing.':'The lantern gutters out, and the forsaken road falls silent. Rise again, knight.';ui.start.textContent=win?'Ride again':'Rise again';ui.hint.textContent='Tap or press ENTER to begin again';ui.overlay.classList.remove('hidden')}
 function updateHud(){ui.healthFill.style.width=(player.hp/player.max*100)+'%';ui.healthText.textContent=Math.ceil(player.hp)+' / 100';ui.waveText.textContent=`WAVE ${wave} / 3`;ui.waveLabel.textContent=wave===1?'NIGHTFALL':wave===2?'THE HUNT':'LAST LIGHT';ui.killText.textContent=kills}
 function notify(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=1.8}
-function spawnEnemy(){let type=(wave===1?Math.random()<.68:'x')? 'goblin':'skeleton';if(wave===3&&Math.random()<.48)type='skeleton';const side=Math.random()<.5?-1:1;enemies.push({type,x:side<0?rand(70,170):rand(790,890),y:rand(305,420),hp:type==='goblin'?2:3,max:type==='goblin'?2:3,speed:type==='goblin'?rand(38,51):rand(25,34),face:side<0?1:-1,attack:rand(.3,1),flash:0,walk:rand(0,6),dead:false});remaining--}
+function spawnEnemy(){let type=wave===1?(Math.random()<.68?'goblin':'skeleton'):(Math.random()<.5?'goblin':'skeleton');if(wave===3&&Math.random()<.48)type='skeleton';const side=Math.random()<.5?-1:1;enemies.push({type,x:side<0?rand(70,170):rand(790,890),y:rand(305,420),hp:type==='goblin'?2:3,max:type==='goblin'?2:3,speed:type==='goblin'?rand(38,51):rand(25,34),face:side<0?1:-1,attack:rand(.3,1),flash:0,walk:rand(0,6),dead:false});remaining--}
 function puff(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-75,75),vy:rand(-100,35),life:rand(.25,.65),max:.65,size:rand(2,5),color})}
 function beginAttack(){if(gameState!=='playing'||player.attackCd>0||player.roll>0)return;player.attack=.25;player.attackCd=.48;playTone(170,.07,'sawtooth',.025);for(const e of enemies){if(e.dead)continue;const dx=e.x-player.x,dy=e.y-player.y;if(Math.abs(dx)<88&&Math.abs(dy)<58&&(Math.sign(dx)===player.face||Math.abs(dx)<23)){e.hp--;e.flash=.16;puff(e.x,e.y-16,'#f2c579',6);shake=4;playTone(95,.08,'triangle',.045);if(e.hp<=0){e.dead=true;kills++;puff(e.x,e.y,'#b8d5d0',14);if(Math.random()<.16)player.hp=Math.min(100,player.hp+12);updateHud()}}}}
 function dodge(){if(gameState!=='playing'||player.rollCd>0)return;player.roll=.24;player.rollCd=.75;player.invuln=.31;playTone(260,.09,'triangle',.02)}
 function playTone(freq,duration,type='sine',volume=.025){if(!sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}

